// Generated from Natural Earth 1:110m admin-0 countries, 1:10m airports,
// and 1:10m populated places (simple), filtered to major/type=major
// airports and pop_max>=1,000,000 or national-capital cities. Raw
// lon/lat, not pre-projected: this data is projected live through
// Leaflet's own latLngToContainerPoint, same as every marker already is,
// so it stays correct at any pan/zoom instead of being baked in for one
// fixed view (see VectorBasemap.tsx).
//
// Two later additions, generated the same way (fetched, matched, Douglas-
// Peucker-simplified, merged in — see this repo's own history for the
// generation step, not re-derivable from this file alone):
//   - CityFeature.outline: Natural Earth 1:50m urban-area polygons
//     (github.com/nvkelso/natural-earth-vector's geojson mirror),
//     nearest-matched to an existing CITIES entry within ~0.35 degrees
//     and simplified (RDP, eps=0.008deg). Present for 469 of 602 cities
//     — the rest have no urban-area polygon at this scale, or none close
//     enough to trust the match; those just keep drawing as a dot, same
//     as before this existed.
//   - AirportFeature.runways: OurAirports' open runway dataset
//     (davidmegginson.github.io/ourairports-data), joined on IATA code,
//     closed runways excluded. Real runway centerlines, not a synthetic
//     "airport outline" shape — genuinely recognizable as an airport at
//     high zoom without inventing geometry no source actually has.
//     Present for 374 of 386 airports.

export interface CountryFeature {
  name: string;
  rings: [number, number][][];
  label: [number, number] | null;
}
export interface AirportFeature {
  name: string;
  code: string;
  pos: [number, number];
  /** Real runway centerlines (each a [start, end] pair, lon/lat) — see file header. Absent for a handful of airports with no matching runway data. */
  runways?: [number, number][][];
}
export interface CityFeature {
  name: string;
  pos: [number, number];
  pop: number;
  capital: boolean;
  /** Simplified urban-area boundary ring (lon/lat) — see file header. Absent below Natural Earth's 1:50m urban-area threshold or with no close-enough match; falls back to a dot. */
  outline?: [number, number][];
}

